import{_ as n,l as r,o as e,c as o,v as i,p as s,x as t,d,i as p,S as _}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"KKT 条件","description":"","frontmatter":{"title":"KKT 条件","date":"2026-09-10T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/kkt-conditions.md","filePath":"econ/kkt-conditions.md","lastUpdated":1789023840000}'),E={name:"econ/kkt-conditions.md"};function h(m,a,c,u,A,g){const l=r("Mermaid");return e(),o("div",null,[a[1]||(a[1]=i('<h1 id="kkt-条件" tabindex="-1">KKT 条件 <a class="header-anchor" href="#kkt-条件" aria-label="Permalink to &quot;KKT 条件&quot;">​</a></h1><div class="epigraph"><p>不等式把可行方向收成锥；互补松弛说：没顶上的约束，乘子必须为零。</p><footer>—— 据 Boyd and Vandenberghe, Convex Optimization, 第 5 章；Mas-Colell, Whinston and Green 数学附录整理</footer></div><p>上一课<a href="/econ/lagrange-multiplier">拉格朗日乘子</a>处理 \\(h(x)=0\\)。消费非负、产能上限、激励相容里的参与约束，都是不等式。缺口是：有的约束在最优处松弛（乘子应为零），有的绷紧（回到等式乘子）。KKT 把两者写在同一组条件里。本课只补这一块，不重写无约束 FONC，也不把数值求解器讲一遍。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(\\max f(x)\\) s.t. \\(g_i(x)\\le 0\\)、\\(h_j(x)=0\\)。在约束品性（如 Slater：凸问题存在严格可行点；或 LICQ）下，最优 \\(x^*\\) 存在乘子 \\(\\mu\\ge 0\\)、\\(\\lambda\\) 使</p><ol><li>平稳：\\(\\nabla f(x^*)=\\sum_i\\mu_i\\nabla g_i(x^*)+\\sum_j\\lambda_j\\nabla h_j(x^*)\\)（按最大化、约束 \\(\\le 0\\) 的符号书写；最小化则目标梯度变号约定需一致）；</li><li>原可行：\\(g(x^*)\\le 0\\)、\\(h(x^*)=0\\)；</li><li>对偶可行：\\(\\mu\\ge 0\\)；</li><li>互补松弛：\\(\\mu_i g_i(x^*)=0\\)。</li></ol><p>互补松弛是新信息：要么 \\(g_i(x^*)=0\\)（约束生效），要么 \\(\\mu_i=0\\)（影子价格为零）。角点消费 \\(x_k=0\\) 时，该商品的「买更多」方向被挡住，\\(\\partial u/\\partial x_k\\le\\lambda p_k\\)，差用 \\(\\mu_k\\) 补上。后课<a href="/econ/interior-corner">内点与角点</a>直接用这组互补。</p><h3 id="互补不是「两个约束各满足一半」" tabindex="-1">互补不是「两个约束各满足一半」 <a class="header-anchor" href="#互补不是「两个约束各满足一半」" aria-label="Permalink to &quot;互补不是「两个约束各满足一半」&quot;">​</a></h3><p>\\(\\mu_i g_i=0\\) 不是把约束满足到一半。它是逐坐标的择一：松约束的乘子精确为零，紧约束的乘子自由（只非负）。不要读成「平均意义上互补」。Slackness 失败（\\(\\mu_i\\gt 0\\) 且 \\(g_i\\lt 0\\)）在正则问题里不会出现；若数据里看到，多半是约束写反或乘子符号约定乱了。</p><p><span class="marginnote">Slater 对凸问题足够；非凸问题 KKT 可以既不必要也不充分。主干的消费者、成本最小化走凸，一阶当充分用。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把有效约束（最优处取等号的那些 \\(g_i\\)）收成等式，上一课的 Lagrange 作用在这个有效集合上；无效约束的乘子置零。KKT 是对「哪一批约束有效」的事先未知版本：乘子与松紧一起解。</p><p>凸问题（凹目标、凸 \\(g\\)、仿射 \\(h\\)）在 Slater 下：KKT 必要且充分，强对偶成立，最优值等于对偶问题最优值。这是后课成本函数、利润函数可用对偶变量刻画的许可。非凸激励约束（道德风险里的 IC）常常破坏 Slater 与凸，KKT 变成「先写、再验证」，不是自动充分。</p>',13)),(e(),s(_,null,{default:t(()=>[p(l,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20TD%0A%20%20INEQ%5B%22%E4%B8%8D%E7%AD%89%E5%BC%8F%20g%20%E5%B0%8F%E4%BA%8E%E7%AD%89%E4%BA%8E%200%22%5D%20--%3E%20COMP%5B%22%E4%BA%92%E8%A1%A5%EF%BC%9Amu%20%E4%B9%98%20g%20%E7%AD%89%E4%BA%8E%200%22%5D%0A%20%20EQ%5B%22%E7%AD%89%E5%BC%8F%20h%20%E7%AD%89%E4%BA%8E%200%22%5D%20--%3E%20STAT%5B%22%E5%B9%B3%E7%A8%B3%EF%BC%9A%E6%A2%AF%E5%BA%A6%E5%8C%B9%E9%85%8D%22%5D%0A%20%20COMP%20--%3E%20STAT%0A%20%20STAT%20--%3E%20CORNER%5B%22%E8%A7%92%E7%82%B9%EF%BC%9A%E9%83%A8%E5%88%86%20mu%20%E4%B8%BA%E6%AD%A3%22%5D%0A%20%20STAT%20--%3E%20INT%5B%22%E5%86%85%E7%82%B9%EF%BC%9Amu%20%E5%85%A8%E9%9B%B6%EF%BC%8C%E5%9B%9E%E5%88%B0%20Lagrange%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=i('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>可行方向锥是：不进入 \\(g_i\\gt 0\\)、不离开 \\(h=0\\) 的方向。最优要求目标在这个锥上不能再升，故 \\(\\nabla f\\) 落在约束梯度的锥组合里——这仍是<a href="/econ/separating-hyperplane">分离超平面</a>的法锥版。\\(\\mu_i\\ge 0\\) 来自不等式的方向性：只能「推向可行一侧」，不能把乘子写成任意实数。</p><p>内点解全体 \\(g_i\\lt 0\\)，于是全体 \\(\\mu_i=0\\)，KKT 退回无约束或纯等式 Lagrange。所以内点不是另一种理论，是 KKT 的退化。角点是另一退化：若干坐标约束生效。后课画两商品图的切点与轴上端点，就是这两种退化。</p><p><span class="marginnote">互补松弛让包络只对绷紧的约束计数。松掉的资源影子价格为零：再给一单位也绑不到最优值上。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲二次规划算法、有效集法、内点法。也不把 KKT 推广到抽象 Banach 空间的 Lagrange 乘子。互补松弛在离散选择、整数约束上要换成分支，不在主干。下一课问：参数动时，最优<strong>值</strong>怎么变——乘子正是那条导数。</p><p>后课默认：带不等式的光滑凸规划，最优写成 KKT；角点用互补松弛读，不把 \\(\\nabla u=\\lambda p\\) 强加在零消费上。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>KKT = 平稳 + 可行 + \\(\\mu\\ge 0\\) + 互补松弛。</li><li>松约束乘子为零；紧约束回到 Lagrange。</li><li>凸加 Slater：必要且充分，并对偶间隙为零。</li><li>内点与角点都是 KKT 的特例，不是另一套理论。</li><li>下一课：<a href="/econ/envelope-theorem">包络定理</a>。</li><li>出处：Boyd and Vandenberghe 第 5 章；MWG 数学附录。</li></ul>',9))])}const K=n(E,[["render",h]]);export{T as __pageData,K as default};
